<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { obtenerConfiguracion } from '../services/calculadoraConsumo'
import type { ConfiguracionCalculadora, Estructura, Tramo } from '../interfaces/calculadoraConsumo.interface'
interface Resultado{nombre:string;agua:number;alcantarillado:number;cargoFijo:number;subtotal:number;igv:number;redondeo:number;total:number;vigente:boolean}
const config=ref<ConfiguracionCalculadora>({distritos:[],categorias:[],estructuras:[],igv:.18}),loading=ref(false),error=ref(''),calculated=ref(false)
const form=reactive({distrito_id:'',categoria_id:'',volumen:0,beneficio:false,agua:true,alcantarillado:true})
const distrito=computed(()=>config.value.distritos.find(x=>x.id===Number(form.distrito_id))),categoria=computed(()=>config.value.categorias.find(x=>x.id===Number(form.categoria_id)))
function importe(tramos:Tramo[],beneficio=false){let anterior=0,total=0,restante=Math.max(0,Number(form.volumen));for(const tramo of tramos){const limite=Number(tramo.maximo_consumo);const cantidad=Math.max(0,Math.min(restante,limite-anterior));const factor=beneficio?Number(tramo.factor_beneficio||1):1;total+=cantidad*Number(tramo.valor)*factor;restante-=cantidad;anterior=limite;if(restante<=0)break}return round(total)}
const resultados=computed<Resultado[]>(()=>{if(!calculated.value)return[];const key=`${form.distrito_id}:${form.categoria_id}`;return config.value.estructuras.filter(x=>x.vigente||x.proyecto).map((e:Estructura)=>{const t=e.tarifas[key]||{agua:[],alcantarillado:[]};const agua=form.agua?importe(t.agua,form.beneficio&&Number(form.categoria_id)===1):0;const alcantarillado=form.alcantarillado?importe(t.alcantarillado):0;const cargoFijo=round(Number(e.cargo_fijo));const subtotal=round(agua+alcantarillado+cargoFijo),igv=round(subtotal*Number(config.value.igv??.18));const bruto=subtotal+igv,redondeo=round(-(bruto*10-Math.trunc(bruto*10))/10);return{nombre:e.nombre,agua,alcantarillado,cargoFijo,subtotal,igv,redondeo,total:round(bruto+redondeo),vigente:e.vigente}})})
function round(n:number){return Math.round((n+Number.EPSILON)*100)/100}function money(n:number){return n.toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})}
function calculate(){error.value='';if(!form.distrito_id||!form.categoria_id||form.volumen<0){error.value='Seleccione distrito y categoría e ingrese un volumen válido.';return}if(!form.agua&&!form.alcantarillado){error.value='Seleccione al menos un servicio.';return}calculated.value=true}
async function load(){loading.value=true;try{config.value=await obtenerConfiguracion();form.distrito_id=String(config.value.distritos[0]?.id||'');form.categoria_id=String(config.value.categorias[0]?.id||'')}catch(e){error.value=e instanceof Error?e.message:'No se pudo cargar la estructura tarifaria.'}finally{loading.value=false}}onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Calculadora de consumo</nav><header class="hero"><div class="mark">m³</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Calculadora de consumo</h1><p>Simulación del recibo según la estructura tarifaria de la empresa.</p></div><span>{{config.estructuras.filter(x=>x.vigente||x.proyecto).length}} estructuras</span></header><p v-if="error" class="flash">{{error}}</p><div v-if="loading" class="empty">Cargando tarifas…</div><main v-else><form class="panel form" @submit.prevent="calculate"><header><b>Datos de simulación</b><small>Complete los criterios del suministro</small></header><label>Distrito<select v-model="form.distrito_id" required><option value="">Seleccione</option><option v-for="x in config.distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Categoría<select v-model="form.categoria_id" required><option value="">Seleccione</option><option v-for="x in config.categorias" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Volumen consumido (m³)<input v-model.number="form.volumen" type="number" min="0" step="0.01" required></label><label class="check"><input v-model="form.beneficio" type="checkbox"> Beneficio por zona estratificada</label><hr><b class="subtitle">Servicios a calcular</b><label class="check"><input v-model="form.agua" type="checkbox"> Servicio de agua potable</label><label class="check"><input v-model="form.alcantarillado" type="checkbox"> Servicio de alcantarillado</label><button>Calcular importe</button><p class="hint">El beneficio tarifario solo aplica a la categoría correspondiente.</p></form><section class="results"><div v-if="!resultados.length" class="empty"><b>Resultado de la simulación</b><span>Ingrese los datos y pulse “Calcular importe”.</span></div><article v-for="r in resultados" :key="r.nombre" class="panel receipt" :class="{project:!r.vigente}"><header><small>{{r.vigente?'ESTRUCTURA VIGENTE':'ESTRUCTURA PROYECTADA'}}</small><h2>{{r.nombre}}</h2></header><div class="context"><span>{{distrito?.nombre}}</span><span>{{categoria?.nombre}}</span><b>{{form.volumen}} m³</b></div><p v-if="form.beneficio" class="notice">{{Number(form.categoria_id)===1?'Cálculo con beneficio de zona estratificada':'La categoría seleccionada no aplica el beneficio'}}</p><dl><div><dt>Agua</dt><dd>S/ {{money(r.agua)}}</dd></div><div><dt>Alcantarillado</dt><dd>S/ {{money(r.alcantarillado)}}</dd></div><div><dt>Cargo fijo</dt><dd>S/ {{money(r.cargoFijo)}}</dd></div><div class="strong"><dt>Total afecto</dt><dd>S/ {{money(r.subtotal)}}</dd></div><div><dt>IGV ({{config.igv*100}}%)</dt><dd>S/ {{money(r.igv)}}</dd></div><div><dt>Redondeo</dt><dd>S/ {{money(r.redondeo)}}</dd></div><div class="total"><dt>Total estimado</dt><dd>S/ {{money(r.total)}}</dd></div></dl></article></section></main><aside><b>Importante</b> Esta simulación es referencial. El recibo real puede incluir saldos, intereses u otros conceptos no considerados.</aside></div></template>
<style scoped>
.page{--a:#1689a5;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.receipt header small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7d898f;font-size:.65rem}.hero>span{margin-left:auto;font-size:.58rem;font-weight:700}.flash{padding:10px;color:#a13f43;background:#fff0f0;font-size:.63rem}main{margin-top:14px;display:grid;grid-template-columns:300px 1fr;gap:14px}.panel{padding:18px;border-radius:11px;background:#fff}.form header{margin-bottom:16px}.form header b,.form header small{display:block;font-size:.62rem}.form header small,.hint{color:#879399;font-size:.5rem}.form label{display:block;margin-bottom:11px;font-size:.54rem}input,select{width:100%;padding:9px;border:1px solid #d7e0e4;border-radius:6px;font:inherit;font-size:.58rem}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto}.subtitle{font-size:.57rem}.form button{width:100%;padding:10px;border:0;border-radius:7px;color:#fff;background:var(--a);font-size:.58rem}.results{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.empty{min-height:240px;display:flex;flex-direction:column;align-items:center;justify-content:center;grid-column:1/-1;border-radius:11px;color:#8a969c;background:#fff;font-size:.62rem}.empty b{color:#435159}.receipt{padding:0;overflow:hidden}.receipt header{padding:16px 18px;border-bottom:3px solid var(--a);background:#eaf8f8}.receipt.project header{border-color:#d88d3d;background:#fff6e8}.receipt.project header small{color:#b46f26}.receipt h2{margin:3px 0;font-size:.78rem}.context{padding:10px 18px;display:flex;justify-content:space-between;background:#f7f9fa;font-size:.51rem}.notice{margin:10px 18px;padding:7px;text-align:center;color:#167187;background:#eaf8f8;font-size:.49rem}.receipt dl{margin:0;padding:8px 18px 16px}.receipt dl div{padding:8px 2px;display:flex;justify-content:space-between;border-bottom:1px solid #edf0f2;font-size:.55rem}.receipt dd{margin:0;font-weight:700}.strong{font-weight:700}.receipt .total{margin-top:7px;padding:11px;color:#fff;border:0;border-radius:6px;background:var(--a);font-size:.65rem}.project .total{background:#c27a2f}aside{margin-top:12px;padding:11px 14px;border-left:3px solid #d7a43c;background:#fff9e9;font-size:.54rem}@media(max-width:900px){main{grid-template-columns:1fr}.form{display:grid;grid-template-columns:1fr 1fr;gap:8px}.form header,.form hr,.form button,.form .hint{grid-column:1/-1}}@media(max-width:600px){.results,.form{grid-template-columns:1fr}.hero{flex-wrap:wrap}.hero>span{margin-left:0}}
</style>
